const { existsSync } = await import('node:fs');
const src = process.env.SRC_PATH;
const dst = process.env.DST_PATH;
if (!src || !dst) throw new Error('Missing inputs');
if (!existsSync(src)) throw new Error('Source file missing');
globalThis.srcPath = src;
globalThis.dstPath = dst;

const mod = await import('imagemagick');
const im = mod.default || mod;
const widthEnv = process.env.WIDTH;
const heightEnv = process.env.HEIGHT;
const options = { srcPath: globalThis.srcPath, dstPath: globalThis.dstPath };
if (widthEnv) options.width = parseInt(widthEnv, 10);
if (heightEnv) options.height = parseInt(heightEnv, 10);
await new Promise((resolve, reject) => {
  im.resize(options, (err, stdout, stderr) => {
    if (err) reject(err);
    else resolve();
  });
});
globalThis.success = true;
